"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["5437"],{8091(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>w,frontMatter:()=>d,contentTitle:()=>c,toc:()=>m,assets:()=>u});var n=JSON.parse('{"id":"m1-how-llms-work/lesson","title":"Lesson: How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache","description":"You are the platform engineer for a team that just shipped an internal assistant on top of a language model. It worked fine in the demo. Two weeks later, three things land on your desk in the same week. The model bill has jumped, and nobody changed the code. A latency dashboard shows the assistant getting slower for exactly the long questions your senior engineers ask most. And in a capacity review, someone asks you a simple question you cannot answer yet: how many users can one box hold at the same time?","source":"@site/docs/m1-how-llms-work/lesson.md","sourceDirName":"m1-how-llms-work","slug":"/m1-how-llms-work/lesson","permalink":"/305-llmops/docs/m1-how-llms-work/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache"},"sidebar":"courseSidebar","previous":{"title":"Environment","permalink":"/305-llmops/docs/setup/environment"},"next":{"title":"Lab: How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache","permalink":"/305-llmops/docs/m1-how-llms-work/lab"}}'),s=o(4848),a=o(8453),r=o(6540),i=o(6497);function h({src:e,title:t="Slides"}){let o=(0,i.Ay)(e);return(0,s.jsxs)("div",{className:"deck_nWXz",children:[(0,s.jsxs)("div",{className:"bar_dOoE",children:[(0,s.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,s.jsx)("a",{className:"full_PrDQ",href:o,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,s.jsx)("div",{className:"frame_M4DO",children:(0,s.jsx)("iframe",{src:o,title:t,loading:"lazy",allowFullScreen:!0})})]})}function l({src:e,title:t="Interactive",ratio:o="16 / 9"}){let n=(0,i.Ay)(e),a=(0,r.useRef)(null),h=(0,r.useCallback)(()=>{let e=a.current;e&&(document.fullscreenElement?document.exitFullscreen():e.requestFullscreen?.())},[]);return(0,s.jsxs)("div",{className:"box_rIgf",children:[(0,s.jsxs)("div",{className:"bar_GZkM",children:[(0,s.jsxs)("span",{className:"label_Fo1D",children:["\u{1F579} ",t]}),(0,s.jsxs)("span",{className:"actions_M17N",children:[(0,s.jsx)("button",{type:"button",className:"btn_nJeE",onClick:h,children:"\u26F6 Fullscreen"}),(0,s.jsx)("a",{className:"full_vR5f",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open in new tab \u2197"})]})]}),(0,s.jsx)("div",{ref:a,className:"frame_X9K3",style:{aspectRatio:o},children:(0,s.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}let d={sidebar_position:1,title:"Lesson: How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache"},c="How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache",u={},m=[{value:"Tokens \u2014 you pay per word-piece, not per idea",id:"tokens--you-pay-per-word-piece-not-per-idea",level:2},{value:"The model generates one token at a time",id:"the-model-generates-one-token-at-a-time",level:2},{value:"Prefill and decode \u2014 two very different phases",id:"prefill-and-decode--two-very-different-phases",level:2},{value:"The KV cache \u2014 the notes the model keeps so it never re-reads",id:"the-kv-cache--the-notes-the-model-keeps-so-it-never-re-reads",level:2},{value:"What you&#39;ll do next",id:"what-youll-do-next",level:2}];function p(e){let t={admonition:"admonition",blockquote:"blockquote",code:"code",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"how-llms-work--tokens-prefilldecode--the-kv-cache",children:"How LLMs Work \u2014 Tokens, Prefill/Decode & the KV Cache"})}),"\n",(0,s.jsx)(t.p,{children:"You are the platform engineer for a team that just shipped an internal assistant on top of a language model. It worked fine in the demo. Two weeks later, three things land on your desk in the same week. The model bill has jumped, and nobody changed the code. A latency dashboard shows the assistant getting slower for exactly the long questions your senior engineers ask most. And in a capacity review, someone asks you a simple question you cannot answer yet: how many users can one box hold at the same time?"}),"\n",(0,s.jsx)(t.p,{children:"All three questions have the same root. They are about what the model is actually doing when it answers, and what that work costs. Not the maths of training a model. The runtime. What happens between the request going in and the answer coming out. Once you can see that clearly, the bill, the latency, and the capacity number stop being mysteries. They become things you can read off a request and reason about."}),"\n",(0,s.jsx)(t.p,{children:"That is the whole job of this module. We will build the model's runtime from the ground up, but every idea will land on one of those three ops questions: what am I billed on, why is this slow, and how many users fit. You run production. You do not need the model theory for its own sake. You need exactly enough of it to make these calls with confidence."}),"\n","\n",(0,s.jsx)(h,{src:"decks/m1-concepts.html",title:"M1 \u2014 How LLMs Work: Tokens, Prefill/Decode & the KV Cache"}),"\n",(0,s.jsx)(t.h2,{id:"tokens--you-pay-per-word-piece-not-per-idea",children:"Tokens \u2014 you pay per word-piece, not per idea"}),"\n",(0,s.jsx)(t.p,{children:"Start with the unit. Before we talk about the model at all, we have to talk about how it reads."}),"\n",(0,s.jsxs)(t.p,{children:["A language model does not read words the way you do. It reads ",(0,s.jsx)(t.strong,{children:"tokens"}),". A token is a piece of text, that is a chunk that might be a whole word, a part of a word, a space, or a punctuation mark. The model has a fixed dictionary of these pieces, and every bit of text you send in gets chopped into pieces from that dictionary before the model sees anything."]}),"\n",(0,s.jsx)(t.p,{children:'Imagine an old telegram office. You do not pay per idea you want to send. You pay per word. So people learned to write tight: "arriving monday send car" instead of "I will be arriving on Monday, please could you send a car to pick me up." Same idea, very different cost, because the office counts pieces, not meaning.'}),"\n",(0,s.jsx)(t.p,{children:"A language model bills you the same way. It counts tokens, not ideas. And here is the catch that surprises most teams. The number of tokens is not the number of words. A common English word is often one token. A rare word, a long technical term, or a word in a language the dictionary was not mostly built on gets split into several pieces. Code splits differently again, because all those brackets and underscores are their own pieces."}),"\n",(0,s.jsx)(t.mermaid,{value:"flowchart LR\n  T[\"restart the payments pod\"] --\x3e TK[\"tokenizer<br/>(BPE dictionary)\"]\n  TK --\x3e P[\"'restart' \xb7 ' the' \xb7 ' payments' \xb7 ' pod'\"]\n  P --\x3e N[\"token count = 4<br/>this is what you pay for\"]"}),"\n",(0,s.jsxs)(t.p,{children:["Why does this matter to you, and not just to a data scientist? Because tokens are the billing unit and the capacity unit of every LLM system you will ever run. When a hosted model charges you, it charges per token in and per token out. When you self-host, the model has a ",(0,s.jsx)(t.strong,{children:"context window"}),", that is a hard limit on how many tokens it can hold at once, and every token of the prompt eats into that budget. So the same feature written two different ways can cost you twice as much and hit the context limit twice as fast, with no change in what the user actually asked."]}),"\n",(0,s.jsx)(t.p,{children:'The mystery bill from the start of this lesson often lives right here. Someone made the system prompt longer, or the documents you stuff into each request grew, and the token count per call crept up. Nobody "changed the code" in the way they meant. But every call now carries more tokens, and tokens are the meter. In the lab you will run the real tokenizer over English, Hindi, and a line of code, and watch the same instruction cost a different number of tokens each time. That is the meter you are billed on, made visible.'}),"\n",(0,s.jsx)(t.admonition,{title:"The one habit to carry out of this section",type:"tip",children:(0,s.jsx)(t.p,{children:'When you reason about cost or capacity, count in tokens, not words. "This prompt is two hundred words" tells you almost nothing. "This prompt is three hundred and forty tokens, and we send it on every request" tells you exactly what it costs and how much of the context window it burns.'})}),"\n",(0,s.jsx)(t.h2,{id:"the-model-generates-one-token-at-a-time",children:"The model generates one token at a time"}),"\n",(0,s.jsx)(t.p,{children:"Now the model itself. We keep it to the working idea, no maths wall."}),"\n",(0,s.jsxs)(t.p,{children:["A modern chat model is a ",(0,s.jsx)(t.strong,{children:"decoder-only"})," model, and it does one thing: given all the tokens so far, it predicts the single most likely next token. That is it. It does not write a sentence in one shot. It writes one token, sticks it onto the end of what it has, and then runs the whole thing again to get the next token. Then again. And again. Until it decides to stop."]}),"\n",(0,s.jsxs)(t.p,{children:["Imagine a very well-read person playing a word-at-a-time game. You give them the start of a sentence. They read the whole thing so far, think, and say the next word. Then they read the whole thing again, now including the word they just said, and give you the word after that. They never skip ahead. Every new word is a fresh read of everything up to that point. This one-at-a-time, always-look-back behaviour is called ",(0,s.jsx)(t.strong,{children:"autoregressive"})," generation, and it is the single most important fact about how these models run."]}),"\n",(0,s.jsx)(t.p,{children:"Here is the path a token takes on each step:"}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n  IN["all tokens so far"] --\x3e EMB["embeddings<br/>tokens become vectors"]\n  EMB --\x3e ATT["attention<br/>each token looks at the others"]\n  ATT --\x3e NT["predict the<br/>next token"]\n  NT --\x3e APP["append it,<br/>loop again"]\n  APP -.-> IN'}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["The tokens become ",(0,s.jsx)(t.strong,{children:"embeddings"}),", that is each token turns into a list of numbers the model can do maths on."]}),"\n",(0,s.jsxs)(t.li,{children:["Then ",(0,s.jsx)(t.strong,{children:"attention"}),' lets each position look back at the earlier tokens and pull in what matters. This is how the model keeps track of context, that is who "it" refers to, what the question was, which service you named ten tokens ago.']}),"\n",(0,s.jsx)(t.li,{children:"From all that, the model predicts the next token, appends it, and loops."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"The loop is where all the runtime cost lives. A two hundred token answer is not one big computation. It is two hundred trips around this loop, one after another, each one reading everything that came before. Sit with that for a second, because it explains the slow dashboard, and it sets up the next idea, which is the one that pays your rent as an ops person."}),"\n","\n",(0,s.jsx)(l,{src:"sims/m1-prefill-decode.html",title:"Prefill / Decode Visualizer \u2014 where an LLM request spends its time",ratio:"16 / 9"}),"\n",(0,s.jsx)(t.h2,{id:"prefill-and-decode--two-very-different-phases",children:"Prefill and decode \u2014 two very different phases"}),"\n",(0,s.jsx)(t.p,{children:"Every request the model handles runs in two phases, and they behave so differently that you size, bill, and troubleshoot them separately. This is the most useful idea in the whole module, so we will take it slowly."}),"\n",(0,s.jsx)(t.p,{children:"Imagine you sit an exam. First you read the whole question paper. You can read it all at once, eyes moving fast, taking it in. That reading is quick and you do it in one go. Then you start writing your answer. And writing is slow, one word after another, because each sentence you write depends on the one before it. You cannot write the last line of your answer before the first. Reading the paper is one kind of work. Writing the answer is a completely different kind."}),"\n",(0,s.jsx)(t.p,{children:"The model works the same way, and the two phases even have names."}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Prefill"})," is the model reading your whole prompt. Because all the prompt tokens are already there, the model can process them together, in one big parallel go. This phase is ",(0,s.jsx)(t.strong,{children:"compute-bound"}),", that is the limit is raw processing power. Prefill is where ",(0,s.jsx)(t.strong,{children:"TTFT"})," comes from, that is ",(0,s.jsx)(t.em,{children:"time to first token"}),", the wait from when you hit send to when the first word of the answer appears. A long prompt means a long read, which means a longer wait before anything shows up."]}),"\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Decode"})," is the model writing the answer, one token at a time, that word-at-a-time loop from the last section. It cannot go parallel, because each token depends on the one before it. This phase is ",(0,s.jsx)(t.strong,{children:"memory-bandwidth-bound"}),", that is the limit is how fast the hardware can move the model's weights and its running notes in and out of memory for each step, not raw compute. Decode is where ",(0,s.jsx)(t.strong,{children:"TPOT"})," comes from, that is ",(0,s.jsx)(t.em,{children:"time per output token"}),", the steady rhythm at which words appear after the first one. A long answer means many decode steps, which means a longer total time, but the first word can still show up fast."]}),"\n",(0,s.jsx)(t.mermaid,{value:'flowchart LR\n  subgraph PRE["prefill \u2014 read the whole prompt"]\n    direction LR\n    P1["all prompt tokens<br/>processed together"]\n  end\n  subgraph DEC["decode \u2014 write the answer"]\n    direction LR\n    D1["token"] --\x3e D2["token"] --\x3e D3["token"] --\x3e D4["..."]\n  end\n  PRE --\x3e|"first token appears = TTFT"| DEC\n  DEC --\x3e|"steady rhythm = TPOT"| OUT["answer complete"]'}),"\n",(0,s.jsxs)(t.p,{children:["So here is the rule to remember. ",(0,s.jsx)(t.strong,{children:"TTFT is mostly about how long your prompt is. TPOT is mostly about how long your answer is."}),' Two different phases, two different numbers, two different fixes. When someone says "the assistant feels slow", your first question is now: slow to ',(0,s.jsx)(t.em,{children:"start"}),", or slow to ",(0,s.jsx)(t.em,{children:"finish"}),"? Those send you to two completely different places."]}),"\n",(0,s.jsx)(t.p,{children:'Go back to the latency dashboard from the start of the lesson. It got slower for the long questions your senior engineers ask. A long question means a long prompt, which means a long prefill, which means a high TTFT. The users were not imagining it, and the fix is not "make the model faster" in general. The fix is on the prompt length, because that is the phase that grew. You could not even have that conversation before this section. Now you can measure it.'}),"\n",(0,s.jsxs)(t.p,{children:["In the lab you will send two requests to the real model. One with a big prompt and a one-word answer, so almost all the work is prefill. One with a tiny prompt and a long answer, so almost all the work is decode. Then you will read the model's own timing numbers and watch the split flip from one phase to the other. You will ",(0,s.jsx)(t.em,{children:"measure"})," the two phases on your own machine, not take my word for it."]}),"\n",(0,s.jsx)(t.h2,{id:"the-kv-cache--the-notes-the-model-keeps-so-it-never-re-reads",children:"The KV cache \u2014 the notes the model keeps so it never re-reads"}),"\n",(0,s.jsx)(t.p,{children:"One more idea, and it ties the room together. It also answers your capacity question."}),"\n",(0,s.jsx)(t.p,{children:"Remember the autoregressive loop: every new token is a fresh look back at all the earlier tokens. Read that literally and it sounds terrible. For token number five hundred, does the model really re-process all four hundred and ninety-nine tokens before it? If it did, long answers would get slower and slower with every word, and generation would grind to a halt. It does not, and the reason is a cache."}),"\n",(0,s.jsxs)(t.p,{children:["When the model processes a token in attention, it computes two things for that token, called its ",(0,s.jsx)(t.strong,{children:"key"})," and its ",(0,s.jsx)(t.strong,{children:"value"}),'. These are the token\'s contribution to the "look back", that is what later tokens will read when they attend to this position. Here is the important part. Once computed for a token, they never change. So the model computes them once and keeps them. This store is the ',(0,s.jsx)(t.strong,{children:"KV cache"}),", that is the key-value cache."]}),"\n",(0,s.jsx)(t.p,{children:"Imagine rough work in an exam. You work out a hard sum in the margin. Later questions use that same result. You do not re-derive it each time. You just glance at your rough work and carry the number forward. The KV cache is the model's rough work. Compute each token's key and value once, keep them, and every future token in the answer reads from the cache instead of redoing the work. That is what keeps decode at a steady rhythm instead of slowing to a crawl."}),"\n",(0,s.jsxs)(t.p,{children:["Now, here is the part that pays your rent. The rough work takes space. The KV cache grows by a fixed amount for ",(0,s.jsx)(t.strong,{children:"every token"})," in the request, prompt and answer together, and it stays in memory the whole time that request is alive. So the memory a single request holds is roughly:"]}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"KV cache per request \u2248 (a fixed per-token cost) into (number of tokens in the request)"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"The per-token cost is set by the model's shape, that is its layers and its attention heads, and you can look it up. Multiply by the tokens, and you have the memory that one request pins down. Multiply again by how many requests you want to run at the same time, and you have your capacity answer:"}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"total KV memory \u2248 per-token cost into tokens per request into number of concurrent requests"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"This is the third question from the start of the lesson, the one you could not answer. How many users fit on one box? It is this sum. Your model's weights take a fixed chunk of memory. Whatever is left is your KV budget. Divide that budget by the KV cost of one user's request, and that is roughly how many users fit at once. Not a guess. A calculation you can do on the back of an envelope before you provision anything."}),"\n",(0,s.jsx)(t.p,{children:"In the lab, the tokenizer script will print this exact table for the course model: the per-token KV cost, then the memory for a few context lengths. When you reach the Kubernetes serving module later in the course, this same number is what you will size a pod's memory limit against and what an autoscaler will watch fill up. You are meeting it here, at the source."}),"\n",(0,s.jsx)(t.admonition,{title:"The three numbers this module gives you",type:"tip",children:(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"Tokens"})," \u2014 the billing and capacity unit. Count in tokens, never words."]}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"TTFT vs TPOT"})," \u2014 the wait to ",(0,s.jsx)(t.em,{children:"start"})," (driven by prompt length, the prefill phase) versus the rhythm of the ",(0,s.jsx)(t.em,{children:"answer"}),' (driven by output length, the decode phase). "Slow" is always one or the other, never just "slow".']}),"\n",(0,s.jsxs)(t.li,{children:[(0,s.jsx)(t.strong,{children:"KV cache math"})," \u2014 per-token cost into tokens into concurrent users. This is your capacity number, and you can compute it before you deploy."]}),"\n"]})}),"\n",(0,s.jsx)(t.h2,{id:"what-youll-do-next",children:"What you'll do next"}),"\n",(0,s.jsxs)(t.p,{children:["In the lab you will pull the course model, ",(0,s.jsx)(t.code,{children:"qwen3:0.6b"}),', and run everything on your own laptop, no GPU. You will make the tokenizer visible: count tokens across English, Hindi, and code, and print the KV-cache table. You will send one request through the OpenAI-compatible API that the whole rest of the course rides on. Then the money shot: two instrumented runs, one prefill-heavy and one decode-heavy, where you read the model\'s own per-phase timings and compute TTFT, TPOT, and tokens per second yourself. You will see what turning on "thinking mode" costs, once, and understand why the course pins it off. And you will open the LLM Stack X-Ray on your own endpoint and watch a real request split into its two phases live.']}),"\n",(0,s.jsx)(t.p,{children:"The model stops being a black box the moment you can read what it is doing and what that work costs. Everything else in this course, that is serving it in production, scaling it, watching it, putting a gateway in front of it, runs on the three numbers you build here."})]})}function w(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(p,{...e})}):p(e)}},8453(e,t,o){o.d(t,{R:()=>r,x:()=>i});var n=o(6540);let s={},a=n.createContext(s);function r(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);